function inspectCookieSecurity(cookieFlags) {
  const hasHttpOnly = cookieFlags.includes('HttpOnly');
  const hasSecure = cookieFlags.includes('Secure');
  const hasSameSite = cookieFlags.includes('SameSite=Strict');

  return {
    resistantToXSSExfiltration: hasHttpOnly,
    secureChannelOnly: hasSecure,
    csrfHardened: hasSameSite
  };
}

const flags = 'Path=/; Secure; HttpOnly; SameSite=Strict';
